CREATE TABLE account (account_id TEXT PRIMARY KEY, alias TEXT NOT NULL, base_currency TEXT NOT NULL, initialized_at TEXT NOT NULL, source_snapshot_hash TEXT NOT NULL UNIQUE);
CREATE TABLE account_import_batch (import_batch_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), invocation_id TEXT NOT NULL UNIQUE, confirmed_as_of TEXT NOT NULL, source_snapshot_hash TEXT NOT NULL UNIQUE, quality_status TEXT NOT NULL, evidence_json TEXT NOT NULL);
CREATE TABLE account_import_source (import_batch_id TEXT NOT NULL REFERENCES account_import_batch(import_batch_id), source_role TEXT NOT NULL, source_schema_version TEXT NOT NULL, object_sha256 TEXT NOT NULL REFERENCES object_blob(sha256), row_count INTEGER NOT NULL, PRIMARY KEY(import_batch_id,source_role));
CREATE TABLE account_cash_opening (account_id TEXT PRIMARY KEY REFERENCES account(account_id), amount_decimal TEXT NOT NULL, currency TEXT NOT NULL, source_row_identity TEXT NOT NULL, source_date TEXT NOT NULL, confirmed_as_of TEXT NOT NULL);
CREATE TABLE account_position (position_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), security_id TEXT NOT NULL REFERENCES security(security_id), source_display_name TEXT NOT NULL, quantity_decimal TEXT NOT NULL, available_decimal TEXT NOT NULL, frozen_decimal TEXT NOT NULL, source_type TEXT NOT NULL CHECK(source_type='opening_snapshot'), UNIQUE(account_id,security_id));
CREATE TABLE account_position_lot (position_lot_id TEXT PRIMARY KEY, position_id TEXT NOT NULL REFERENCES account_position(position_id), quantity_decimal TEXT NOT NULL, cost_price_decimal TEXT NOT NULL, currency TEXT NOT NULL, source_type TEXT NOT NULL CHECK(source_type='opening_snapshot'), source_row_identity TEXT NOT NULL, UNIQUE(position_id));
CREATE TABLE account_position_observation (position_id TEXT PRIMARY KEY REFERENCES account_position(position_id), source_price_decimal TEXT NOT NULL, source_market_value_decimal TEXT NOT NULL, source_day_pnl_decimal TEXT NOT NULL, source_weight_decimal TEXT NOT NULL, source_as_of TEXT NOT NULL);
CREATE TABLE account_import_quality_issue (quality_issue_id TEXT PRIMARY KEY, import_batch_id TEXT NOT NULL REFERENCES account_import_batch(import_batch_id), code TEXT NOT NULL, source_row_identity TEXT NOT NULL, details_json TEXT NOT NULL);
CREATE TABLE portfolio_snapshot (portfolio_snapshot_id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES account(account_id), as_of_date TEXT NOT NULL, cash_decimal TEXT NOT NULL, market_value_decimal TEXT NOT NULL, total_equity_decimal TEXT NOT NULL, reconciliation_status TEXT NOT NULL, source_snapshot_hash TEXT NOT NULL UNIQUE, limitations_json TEXT NOT NULL);
CREATE TRIGGER account_immutable_update BEFORE UPDATE ON account BEGIN SELECT RAISE(ABORT,'ACCOUNT_IMMUTABLE'); END;
CREATE TRIGGER account_position_immutable_update BEFORE UPDATE ON account_position BEGIN SELECT RAISE(ABORT,'ACCOUNT_POSITION_IMMUTABLE'); END;
CREATE TRIGGER account_lot_immutable_update BEFORE UPDATE ON account_position_lot BEGIN SELECT RAISE(ABORT,'ACCOUNT_LOT_IMMUTABLE'); END;
